export default{async fetch(request,env){return await handleRequest(request,env).catch(err=>new Response(JSON.stringify({error:err.message}),{status:500,headers:{"Content-Type":"application/json"}}))}};async function handleRequest(request,env){const url=new URL(request.url);if(request.method==="OPTIONS"){return handleCORS()}if(request.method!=="POST"||url.pathname!=="/chat"){return new Response("Not Found",{status:404})}if(!env.LLMTOKEN){return new Response(JSON.stringify({error:"API token not configured"}),{status:500,headers:{"Content-Type":"application/json"}})}try{const requestData=await request.json();if(!requestData.messages||!Array.isArray(requestData.messages)){return new Response(JSON.stringify({error:"Invalid request: messages array required"}),{status:400,headers:{"Content-Type":"application/json"}})}const groqRequest={model:requestData.model||"openai/gpt-oss-120b",messages:requestData.messages,temperature:requestData.temperature||.7,max_tokens:requestData.max_tokens||1e3,stream:false};const groqResponse=await fetch("https://api.groq.com/openai/v1/chat/completions",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${env.LLMTOKEN}`},body:JSON.stringify(groqRequest)});if(!groqResponse.ok){const errorText=await groqResponse.text();console.error("Groq API Error:",groqResponse.status,errorText);return new Response(JSON.stringify({error:`LLM API error: ${groqResponse.status}`,details:errorText}),{status:groqResponse.status,headers:{"Content-Type":"application/json",...getCORSHeaders()}})}const responseData=await groqResponse.json();return new Response(JSON.stringify(responseData),{status:200,headers:{"Content-Type":"application/json",...getCORSHeaders()}})}catch(error){console.error("Worker Error:",error);return new Response(JSON.stringify({error:"Internal server error",message:error.message}),{status:500,headers:{"Content-Type":"application/json",...getCORSHeaders()}})}}function handleCORS(){return new Response(null,{status:200,headers:getCORSHeaders()})}function getCORSHeaders(){return{"Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"POST, OPTIONS","Access-Control-Allow-Headers":"Content-Type, Authorization","Access-Control-Max-Age":"86400"}}function logRequest(request){console.log({method:request.method,url:request.url,headers:Object.fromEntries(request.headers.entries()),timestamp:(new Date).toISOString()})}